using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectPackModels{
 public static string Run(){var stage=new GameObject("Inspect pack");string report="";try{var names=new[]{"Knight","2Handed","Archer","Mage","Ninja","Swordsman"};int i=0;foreach(string n in names){var path=AssetDatabase.FindAssets(n+" t:Model",new[]{"Assets/ExplosiveLLC"}).Select(AssetDatabase.GUIDToAssetPath).First(x=>x.EndsWith("/"+n+".FBX"));var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path),stage.transform);foreach(var a in g.GetComponentsInChildren<Animator>())a.enabled=false;var renderers=g.GetComponentsInChildren<Renderer>();var b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);g.transform.localScale*=1.8f/b.size.y;g.transform.position=new Vector3(i++*1.2f,-b.min.y*g.transform.localScale.x,0);foreach(var t in g.GetComponentsInChildren<Transform>())t.gameObject.layer=29;foreach(var r in renderers){r.sharedMaterials=r.sharedMaterials.Select(m=>{var c=new Material(Shader.Find("Universal Render Pipeline/Lit"));c.mainTexture=m.mainTexture;c.color=m.HasProperty("_Color")?m.color:Color.white;return c;}).ToArray();}var an=g.GetComponent<Animator>();report+=n+" meshes="+renderers.Length+" humanoid="+(an&&an.avatar&&an.avatar.isHuman)+"\n";}
 var cam=new GameObject("Camera").AddComponent<Camera>();cam.transform.SetParent(stage.transform);cam.transform.position=new Vector3(3,1.1f,8);cam.transform.LookAt(new Vector3(3,.95f,0));cam.orthographic=true;cam.orthographicSize=1.2f;cam.cullingMask=1<<29;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.16f,.17f,.19f);var light=new GameObject("Light").AddComponent<Light>();light.transform.SetParent(stage.transform);light.type=LightType.Directional;light.intensity=2;light.transform.rotation=Quaternion.Euler(40,180,0);light.cullingMask=1<<29;var rt=new RenderTexture(1800,600,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1800,600);tex.ReadPixels(new Rect(0,0,1800,600),0,0);tex.Apply();System.IO.File.WriteAllBytes("D:/67/CindersBackups/Pack-models.png",tex.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);return report;}finally{UnityEngine.Object.DestroyImmediate(stage);}}
}
